referenceSolutionTemplate:
#include <stdio.h>

#define MAX_BOWLS 5

int bowls[MAX_BOWLS];
int top = 0;

int is_full(void) { return top == MAX_BOWLS; }
int is_empty(void) { return top == 0; }

int push(int value) {
    if (is_full()) {
        return 0;
    }
    bowls[top] = value;
    top++;
    return 1;
}

int pop(int *value) {
    if (is_empty()) {
        return 0;
    }
    top--;
    *value = bowls[top];
    return 1;
}

int peek(int *value) {
    if (is_empty()) {
        return 0;
    }
    *value = bowls[top - 1];
    return 1;
}

int main(void) {
    push({a});
    push({b});
    push({c});

    int v = 0;
    peek(&v);
    printf("最上面那只碗里是 %d\n", v);

    pop(&v);
    printf("拿走一只，是 %d\n", v);

    peek(&v);
    printf("现在最上面是 %d\n", v);
    return 0;
}
